/**
 * t3.mjs — a one-shot MCP client for the T3 orchestrator endpoint, dropped
 * into the session workspace at session start when a T3 MCP server is attached.
 *
 * No secrets live in this file: credentials are read from the environment at
 * call time (T3_MCP_URL / T3_MCP_BEARER_TOKEN, injected by letta-acp into the
 * CLI process env, which the agent's shell inherits).
 *
 * Each invocation does the full MCP streamable-HTTP dance (initialize ->
 * tools/call) so there is no session state to go stale; the endpoint is
 * loopback so the extra round trip is free.
 */
export const HELPER_SCRIPT = [
    "#!/usr/bin/env node",
    "// t3.mjs — one-shot MCP client for the T3 orchestrator endpoint.",
    "// Dropped into the workspace by letta-acp; reads T3_MCP_URL and",
    "// T3_MCP_BEARER_TOKEN from the environment at call time.",
    "//",
    "//   node t3.mjs <toolName> [argsJson]   call an orchestrator tool",
    "//   node t3.mjs --list                 list tools (name + description)",
    "const url = process.env.T3_MCP_URL;",
    "const token = process.env.T3_MCP_BEARER_TOKEN;",
    "if (!url || !token) {",
    '  console.error("t3.mjs: T3_MCP_URL / T3_MCP_BEARER_TOKEN are not set (no T3 orchestrator attached to this session).");',
    "  process.exit(2);",
    "}",
    "const headers = {",
    '  "Content-Type": "application/json",',
    '  "Accept": "application/json, text/event-stream",',
    '  "mcp-protocol-version": "2025-06-18",',
    '  "Authorization": "Bearer " + token,',
    "};",
    "async function rpc(method, params, sessionId) {",
    "  const res = await fetch(url, {",
    "    method: \"POST\",",
    "    headers: sessionId ? { ...headers, \"mcp-session-id\": sessionId } : headers,",
    "    body: JSON.stringify({ jsonrpc: \"2.0\", id: 1, method, params }),",
    "  });",
    "  if (!res.ok) throw new Error(\"HTTP \" + res.status + \": \" + (await res.text()).slice(0, 400));",
    "  const sid = res.headers.get(\"mcp-session-id\") || undefined;",
    "  const ct = res.headers.get(\"content-type\") || \"\";",
    "  let payload;",
    "  if (ct.includes(\"text/event-stream\")) {",
    "    const text = await res.text();",
    "    for (const line of text.split(\"\\n\")) {",
    "      if (line.startsWith(\"data:\")) {",
    "        const parsed = JSON.parse(line.slice(5).trim());",
    "        if (parsed.id === 1) { payload = parsed; break; }",
    "      }",
    "    }",
    "  } else {",
    "    payload = await res.json();",
    "  }",
    "  if (!payload) throw new Error(\"no response payload for \" + method);",
    "  if (payload.error) throw new Error(payload.error.message + (payload.error.code ? \" [code \" + payload.error.code + \"]\" : \"\"));",
    "  return { result: payload.result, sessionId: sid };",
    "}",
    "try {",
    "  const init = await rpc(\"initialize\", {",
    "    protocolVersion: \"2025-06-18\",",
    "    capabilities: {},",
    "    clientInfo: { name: \"letta-acp-helper\", version: \"1.0.0\" },",
    "  });",
    "  // MCP initialization notification. T3 does not require it, but send it for correctness.",
    "  fetch(url, {",
    "    method: \"POST\",",
    "    headers: { ...headers, \"mcp-session-id\": init.sessionId },",
    "    body: JSON.stringify({ jsonrpc: \"2.0\", method: \"notifications/initialized\" }),",
    "  }).catch(() => {});",
    "  if (process.argv[2] === \"--list\") {",
    "    const tools = ((await rpc(\"tools/list\", {}, init.sessionId)).result.tools) || [];",
    "    for (const t of tools) console.log(t.name + \" — \" + (t.description || \"\").split(\"\\n\")[0]);",
    "  } else {",
    "    const name = process.argv[2];",
    "    if (!name) { console.error(\"usage: node t3.mjs <toolName> [argsJson]  |  node t3.mjs --list\"); process.exit(2); }",
    "    const args = process.argv[3] ? JSON.parse(process.argv[3]) : {};",
    "    const r = (await rpc(\"tools/call\", { name, arguments: args }, init.sessionId)).result;",
    "    const text = (r.content || []).filter((c) => c.type === \"text\").map((c) => c.text).join(\"\\n\");",
    "    if (text) console.log(text);",
    "    if (r.isError) { console.error(\"t3.mjs: tool reported an error\"); process.exit(1); }",
    "  }",
    "} catch (err) {",
    "  console.error(\"t3.mjs: \" + (err && err.message ? err.message : String(err)));",
    "  process.exit(1);",
    "}",
].join("\n");
